import sys

def main():
    T = int(sys.stdin.readline())
    for _ in range(T):
        Q = int(sys.stdin.readline())
        S = set()
        even = 0
        odd = 0
        for __ in range(Q):
            X = int(sys.stdin.readline())
            new_elements = set()
            new_elements.add(X)
            for y in S:
                new_elements.add(y ^ X)
            S.update(new_elements)
            current_even = 0
            current_odd = 0
            for num in S:
                if bin(num).count('1') % 2 == 0:
                    current_even += 1
                else:
                    current_odd += 1
            print(current_even, current_odd)

if __name__ == "__main__":
    main()
